import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class CodeforcesVariant3 {

    public static int binarySearch(int value, int[] array) {
        int low = 0;
        int high = array.length - 1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (array[mid] == value) return mid;
            else if (value > array[mid]) low = mid + 1;
            else high = mid - 1;
        }
        return -1;
    }

    public static void main(String[] args) throws IOException {
        InputStream inputStream = System.in;
        BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int n = Integer.parseInt(tokenizer.nextToken());
        int maxCount = 0, countW = 0;
        String s = reader.readLine();
        char[] chars = s.toCharArray();

        for (int i = 0; i < n; i++) {
            if (chars[i] != '_' && chars[i] != '(') {
                int count = 0;
                for (int j = i; j < n; j++) {
                    if (chars[j] != '_' && chars[j] != '(') count++;
                    if (chars[j] == '_' || chars[j] == '(' || j == n - 1) {
                        maxCount = Math.max(maxCount, count);
                        i = j;
                        break;
                    }
                }
            }
            if (chars[i] == '(') {
                int count = 0;
                for (int j = i; j < n; j++) {
                    if ((chars[j] == '_' || chars[j] == ')') && count > 0) {
                        countW++;
                        count = 0;
                    }
                    if (chars[j] == ')') {
                        i = j;
                        break;
                    }
                    if (chars[j] != '_' && chars[j] != '(') count++;
                }
            }
        }
        System.out.println(maxCount + " " + countW);
    }
}
